        assert_eq!(
            harness
                .call(vec![Request::Enroll { claim_code: None }])
                .await[0],
            Response::Denied
        );
        db::enrollment_codes::insert_code(&harness.service.db, "GRANT-1", 3600)
            .await
            .expect("mint");
        assert_eq!(
            harness
                .call(vec![Request::Enroll {
                    claim_code: Some("GRANT-1".into())
