    #[tokio::test]
    async fn one_node_cannot_reach_another_nodes_handle_over_the_wire() {
        let harness = Harness::start(true).await;
        // Node A registers.
        let responses = harness
            .call(vec![
                Request::Enroll { claim_code: None },
                Request::RegisterHandle {
                    apns_token: "tok".into(),
                    apns_topic: "org.obsign.app".into(),
                },
            ])
            .await;
        let Response::Handle { handle } = responses[1].clone() else {
            panic!("expected a handle");
        };

        // Node B is a second, independently-keyed endpoint dialing the same relay.
        let node_b = loopback_endpoint(false).await;
        let conn = node_b
            .connect(harness.server_addr(), ALPN)
            .await
            .expect("connect");
        let ask = |request: Request| {
            let conn = conn.clone();
            async move {
                let (mut send, mut recv) = conn.open_bi().await.expect("open_bi");
                send.write_all(&serde_json::to_vec(&request).expect("encode"))
                    .await
                    .expect("write");
                send.finish().expect("finish");
                let bytes = recv.read_to_end(MAX_MESSAGE_LEN).await.expect("read");
                serde_json::from_slice::<Response>(&bytes).expect("decode")
            }
        };

        assert_eq!(
            ask(Request::Enroll { claim_code: None }).await,
            Response::Ok
        );
        assert_eq!(
            ask(Request::Push {
                handle: handle.clone(),
                kid: 1,
                enc: "e".into(),
                ct: "c".into(),
                priority: None,
                ttl_secs: None,
                ping: None,
            })
            .await,
            Response::Pushed {
                outcome: PushOutcome::UnknownHandle
            }
        );
        assert_eq!(
            ask(Request::DropHandle {
                handle: handle.clone()
            })
            .await,
            Response::Ok
        );
        assert!(
            db::handles::resolve_handle(
                &harness.service.db,
                &harness.client.id().to_string(),
                &handle
            )
            .await
            .expect("resolve")
            .is_some(),
            "node B's drop must not have removed node A's handle"
        );

        node_b.close().await;
        harness.close().await;
    }

    #[tokio::test]
    async fn an_unparseable_request_is_answered_without_echoing_it() {
        let harness = Harness::start(true).await;
        let response = tokio::time::timeout(Duration::from_secs(10), async {
            let conn = harness
                .client
                .connect(harness.server_addr(), ALPN)
                .await
                .expect("connect");
            let (mut send, mut recv) = conn.open_bi().await.expect("open_bi");
            send.write_all(b"{\"type\":\"launchMissiles\"}")
                .await
                .expect("write");
            send.finish().expect("finish");
            let bytes = recv.read_to_end(MAX_MESSAGE_LEN).await.expect("read");
            serde_json::from_slice::<Response>(&bytes).expect("decode")
        })
        .await
        .expect("round trip timed out");

        let Response::BadRequest { reason } = response else {
            panic!("expected a bad-request response, got {response:?}");
        };
        assert!(
            !reason.contains("launchMissiles"),
            "reason echoed the input: {reason}"
        );

        harness.close().await;
    }

    /// A stream that blows the 64 KiB cap dies alone: the connection stays usable and the
    /// next RPC on it is answered normally, rather than the whole peer being cut off.
    #[tokio::test]
    async fn an_oversized_request_does_not_kill_the_connection() {
        let harness = Harness::start(true).await;

        let answered = tokio::time::timeout(Duration::from_secs(10), async {
            let conn = harness
                .client
                .connect(harness.server_addr(), ALPN)
                .await
                .expect("connect");

            // Well past the read cap, so the relay's `read_to_end` fails on this stream.
            let (mut send, mut recv) = conn.open_bi().await.expect("open_bi");
            send.write_all(&vec![b'x'; MAX_MESSAGE_LEN * 2])
                .await
                .expect("write");
            send.finish().expect("finish");
            let _ = recv.read_to_end(MAX_MESSAGE_LEN).await;

            // A second stream on the same connection must still be served.
            let (mut send, mut recv) = conn.open_bi().await.expect("open_bi after oversized");
            send.write_all(&serde_json::to_vec(&Request::Enroll { claim_code: None }).unwrap())
                .await
                .expect("write");
            send.finish().expect("finish");
            let bytes = recv.read_to_end(MAX_MESSAGE_LEN).await.expect("read");
            serde_json::from_slice::<Response>(&bytes).expect("decode")
        })
        .await
        .expect("round trip timed out");

        assert_eq!(answered, Response::Ok);
        harness.close().await;
    }

    #[tokio::test]
    async fn an_unknown_alpn_is_rejected() {
        let harness = Harness::start(true).await;
        let result = tokio::time::timeout(Duration::from_secs(10), async {
            harness
                .client
                .connect(harness.server_addr(), b"ezpds/notify/SOMETHING-ELSE")
                .await
        })
        .await
        .expect("connect attempt timed out");

        assert!(
            result.is_err(),
            "the relay must negotiate only ezpds/notify/0"
        );
        harness.close().await;
    }

    /// The whole pipeline in one exchange: an instance dials over iroh, enrolls, registers
    /// a device, and pushes — and a stand-in Apple receives the notification. This is the
    /// only test that crosses every seam at once (QUIC framing, the store, the APNs leg),
    /// so it is what catches a wiring break that each layer's own tests would miss.
    #[tokio::test]
    async fn a_push_travels_from_an_iroh_dial_all_the_way_to_apple() {
        use wiremock::matchers::method;
        use wiremock::{Mock, MockServer, ResponseTemplate};

        let apple = MockServer::start().await;
        Mock::given(method("POST"))
            .respond_with(ResponseTemplate::new(200))
            .mount(&apple)
            .await;
        let (_key_dir, apns) = crate::apns::tests::client_for(&apple.uri());

        let service = Arc::new(
            RelayService::new(db::test_pool().await, test_config(true)).with_apns(Some(apns)),
        );
        let server = loopback_endpoint(true).await;
        let _accept = spawn_accept_loop(server.clone(), Arc::clone(&service));
        let client = loopback_endpoint(false).await;
        let harness = Harness {
            server,
            client,
            service,
        };

        let responses = harness
            .call(vec![
                Request::Enroll { claim_code: None },
                Request::RegisterHandle {
                    apns_token: "device-token-from-apple".into(),
                    apns_topic: "org.obsign.identitywallet".into(),
                },
            ])
            .await;
        let Response::Handle { handle } = responses[1].clone() else {
            panic!("expected a handle, got {:?}", responses[1]);
        };

        let pushed = harness
            .call(vec![Request::Push {
                handle: handle.clone(),
                kid: 4,
                enc: "ENCAPSULATED".into(),
                ct: "CIPHERTEXT".into(),
                priority: None,
                ttl_secs: Some(120),
                ping: None,
            }])
            .await;
        assert_eq!(
            pushed[0],
            Response::Pushed {
                outcome: PushOutcome::Delivered
            }
        );

        let received = apple.received_requests().await.expect("recorded requests");
        assert_eq!(
            received.len(),
            1,
            "Apple must have been contacted exactly once"
        );
        assert!(
            received[0]
                .url
                .path()
                .ends_with("/device/device-token-from-apple"),
            "the relay must resolve the handle to the device's real token: {}",
            received[0].url
        );
        let body: serde_json::Value = serde_json::from_slice(&received[0].body).expect("JSON");
        assert_eq!(body["ezpds"]["ct"], "CIPHERTEXT");

        let last_push: Option<String> =
            sqlx::query_scalar("SELECT last_push_at FROM handles WHERE handle = ?")
                .bind(&handle)
                .fetch_one(&harness.service.db)
                .await
                .expect("read the delivery stamp");
        assert!(
            last_push.is_some(),
            "a delivered push must stamp the handle as recently live"
        );

        harness.close().await;
    }

    #[tokio::test]
    async fn an_exhausted_budget_throttles_over_the_wire() {
        let mut config = load_from_env_only(&HashMap::new()).expect("defaults");
        config.open_enrollment = true;
        config.rate_limits.registrations_per_hour = 1;
