// pattern: Imperative Shell

//! Queries over every KEK-wrapped column in the schema.
//!
//! The signing-key master key (`EZPDS_SIGNING_KEY_MASTER_KEY`) is an AES-256-GCM
//! key-encryption key (KEK) that wraps every at-rest secret. This module is the
//! single inventory of where that ciphertext lives — one [`SecretFamily`] per
//! wrapped column — plus generic fetch/update functions over the inventory, so
//! the `rewrap` maintenance path can re-encrypt everything without a per-table
//! query function scattered across five sibling modules. Adding a new
//! KEK-wrapped column means adding a variant here; the re-wrap tool then covers
//! it automatically.
//!
//! Like every `db/` module this file only moves opaque ciphertext; decryption
//! and re-encryption live in the caller (`crate::rewrap`).

use sqlx::Sqlite;

/// One KEK-wrapped column: the table, its primary-key column, and the
/// ciphertext column. `ALL` is the exhaustive inventory the re-wrap sweep
/// iterates.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SecretFamily {
    /// Per-account repo signing keys for promoted DIDs (`signing_keys`, V002).
    SigningKeys,
    /// Standard-migration signing-key reservations (`reserved_signing_keys`, V032).
    ReservedSigningKeys,
    /// Mobile DID-ceremony repo keys still on the pending account
    /// (`pending_accounts.repo_signing_private_key_encrypted`, V019; nullable).
    PendingAccounts,
    /// Operator-level relay signing keys (`relay_signing_keys`, V003).
    RelaySigningKeys,
    /// The server's persistent ES256 OAuth signing key (`oauth_signing_key`, V012).
    OauthSigningKey,
    /// The persistent HS256 JWT signing secret (`jwt_signing_secret`, V015).
    JwtSigningSecret,
    /// The persistent Iroh node Ed25519 secret key (`iroh_identity`, V022).
    IrohIdentity,
    /// PDS-held Shamir escrow shares, legacy server-generated model
    /// (`accounts.recovery_share`, V010).
    RecoveryShares,
    /// PDS-held Shamir Share 2 envelopes, client-generated model
    /// (`recovery_escrow`, V050). The wrapped plaintext is the 42-byte v2
    /// share envelope, not a 32-byte scalar — the re-wrap sweep handles both
    /// via the generic-length `crypto::{encrypt,decrypt}_secret_bytes` pair.
    RecoveryEscrow,
}

impl SecretFamily {
    /// Every KEK-wrapped column in the schema, in sweep order.
    pub const ALL: [SecretFamily; 9] = [
        SecretFamily::SigningKeys,
        SecretFamily::ReservedSigningKeys,
        SecretFamily::PendingAccounts,
        SecretFamily::RelaySigningKeys,
        SecretFamily::OauthSigningKey,
        SecretFamily::JwtSigningSecret,
        SecretFamily::IrohIdentity,
        SecretFamily::RecoveryShares,
        SecretFamily::RecoveryEscrow,
    ];

    /// The owning table name, for reporting and error messages.
    pub fn table(self) -> &'static str {
        match self {
            SecretFamily::SigningKeys => "signing_keys",
            SecretFamily::ReservedSigningKeys => "reserved_signing_keys",
            SecretFamily::PendingAccounts => "pending_accounts",
            SecretFamily::RelaySigningKeys => "relay_signing_keys",
            SecretFamily::OauthSigningKey => "oauth_signing_key",
            SecretFamily::JwtSigningSecret => "jwt_signing_secret",
            SecretFamily::IrohIdentity => "iroh_identity",
            SecretFamily::RecoveryShares => "accounts.recovery_share",
            SecretFamily::RecoveryEscrow => "recovery_escrow",
        }
    }

    /// SELECT for `(id, ciphertext)` over every wrapped row of this family.
    /// `pending_accounts`' key columns are nullable (the key is generated
    /// mid-ceremony), so that query skips NULL rows — there is nothing to
    /// re-wrap on them.
    fn select_sql(self) -> &'static str {
        match self {
            SecretFamily::SigningKeys => "SELECT id, private_key_encrypted FROM signing_keys",
            SecretFamily::ReservedSigningKeys => {
                "SELECT id, private_key_encrypted FROM reserved_signing_keys"
            }
            SecretFamily::PendingAccounts => {
                "SELECT id, repo_signing_private_key_encrypted FROM pending_accounts \
                 WHERE repo_signing_private_key_encrypted IS NOT NULL"
            }
            SecretFamily::RelaySigningKeys => {
                "SELECT id, private_key_encrypted FROM relay_signing_keys"
            }
            SecretFamily::OauthSigningKey => {
                "SELECT id, private_key_encrypted FROM oauth_signing_key"
            }
            SecretFamily::JwtSigningSecret => "SELECT id, secret_encrypted FROM jwt_signing_secret",
            SecretFamily::IrohIdentity => "SELECT id, secret_key_encrypted FROM iroh_identity",
            SecretFamily::RecoveryShares => {
                "SELECT did, recovery_share FROM accounts WHERE recovery_share IS NOT NULL"
            }
            SecretFamily::RecoveryEscrow => "SELECT did, share_encrypted FROM recovery_escrow",
        }
    }

    /// UPDATE writing a re-wrapped ciphertext back to one row by primary key.
    fn update_sql(self) -> &'static str {
        match self {
            SecretFamily::SigningKeys => {
                "UPDATE signing_keys SET private_key_encrypted = ? WHERE id = ?"
            }
            SecretFamily::ReservedSigningKeys => {
                "UPDATE reserved_signing_keys SET private_key_encrypted = ? WHERE id = ?"
            }
            SecretFamily::PendingAccounts => {
                "UPDATE pending_accounts SET repo_signing_private_key_encrypted = ? WHERE id = ?"
            }
            SecretFamily::RelaySigningKeys => {
                "UPDATE relay_signing_keys SET private_key_encrypted = ? WHERE id = ?"
            }
            SecretFamily::OauthSigningKey => {
                "UPDATE oauth_signing_key SET private_key_encrypted = ? WHERE id = ?"
            }
            SecretFamily::JwtSigningSecret => {
                "UPDATE jwt_signing_secret SET secret_encrypted = ? WHERE id = ?"
            }
            SecretFamily::IrohIdentity => {
                "UPDATE iroh_identity SET secret_key_encrypted = ? WHERE id = ?"
            }
            SecretFamily::RecoveryShares => "UPDATE accounts SET recovery_share = ? WHERE did = ?",
            SecretFamily::RecoveryEscrow => {
                "UPDATE recovery_escrow SET share_encrypted = ? WHERE did = ?"
            }
        }
    }
}

/// One KEK-wrapped row: its primary key and the stored ciphertext — the
/// shared `base64(nonce || ciphertext || tag)` envelope of
/// `crypto::encrypt_secret_bytes` (80 base64 chars for the 32-byte key
/// columns; longer for `recovery_escrow`'s 42-byte share envelopes).
#[derive(Debug, Clone)]
pub struct WrappedSecretRow {
    pub id: String,
    pub ciphertext: String,
}

/// Fetch every wrapped row of one family. Generic over the executor so the
/// re-wrap transaction can read and write on the same connection.
pub async fn list_wrapped_secrets<'e, E>(
    executor: E,
    family: SecretFamily,
) -> Result<Vec<WrappedSecretRow>, sqlx::Error>
where
    E: sqlx::Executor<'e, Database = Sqlite>,
{
    let rows: Vec<(String, String)> = sqlx::query_as(family.select_sql())
        .fetch_all(executor)
        .await?;
    Ok(rows
        .into_iter()
        .map(|(id, ciphertext)| WrappedSecretRow { id, ciphertext })
        .collect())
}

/// Write one re-wrapped ciphertext back by primary key. Errors if the row
/// vanished (`RowNotFound`) — inside the re-wrap transaction that can only
/// mean a logic bug, and a silent zero-row update would leave the secret
/// stranded under the old key.
pub async fn update_wrapped_secret<'e, E>(
    executor: E,
    family: SecretFamily,
    id: &str,
    ciphertext: &str,
) -> Result<(), sqlx::Error>
where
    E: sqlx::Executor<'e, Database = Sqlite>,
{
    let result = sqlx::query(family.update_sql())
        .bind(ciphertext)
        .bind(id)
        .execute(executor)
        .await?;
    if result.rows_affected() != 1 {
        return Err(sqlx::Error::RowNotFound);
    }
    Ok(())
}

/// The `server_metadata` key tracking how many KEK rotations have been applied.
/// Absent = 0 (the DB has only ever seen its initial key).
const KEK_GENERATION_KEY: &str = "kek_generation";

/// Read the current KEK generation (0 when the marker has never been written).
pub async fn get_kek_generation<'e, E>(executor: E) -> Result<i64, sqlx::Error>
where
    E: sqlx::Executor<'e, Database = Sqlite>,
{
    let row: Option<(String,)> = sqlx::query_as("SELECT value FROM server_metadata WHERE key = ?")
        .bind(KEK_GENERATION_KEY)
        .fetch_optional(executor)
        .await?;
    Ok(row.and_then(|(v,)| v.parse::<i64>().ok()).unwrap_or(0))
}

/// Upsert the KEK generation marker. Written inside the re-wrap transaction so
/// the marker and the re-encrypted ciphertext commit (or roll back) together.
pub async fn set_kek_generation<'e, E>(executor: E, generation: i64) -> Result<(), sqlx::Error>
where
    E: sqlx::Executor<'e, Database = Sqlite>,
{
    sqlx::query(
        "INSERT INTO server_metadata (key, value) VALUES (?, ?) \
         ON CONFLICT(key) DO UPDATE SET value = excluded.value",
    )
    .bind(KEK_GENERATION_KEY)
    .bind(generation.to_string())
    .execute(executor)
    .await?;
    Ok(())
}

// pattern: Imperative Shell
//
// Iroh QUIC tunnel: a NAT-traversing endpoint devices dial by node id instead of by a
// routable address. Bound at startup (when `[iroh] enabled`) alongside the HTTP server; its
// node id is advertised via `GET /v1/devices/:id/pds`. The accept loop speaks a minimal
// v0.1 echo protocol on the `ezpds/iroh/0` ALPN — enough to prove the bidirectional channel
// works end-to-end and to give devices a liveness probe. The real repo-sync / push protocols
// will register additional ALPNs (or message types) here later.

use iroh::endpoint::{presets, Incoming};
use iroh::{Endpoint, SecretKey};

/// ALPN protocol identifier for the ezpds device↔pds tunnel. Bumped if the wire protocol
/// changes incompatibly.
pub const ALPN: &[u8] = b"ezpds/iroh/0";

/// Upper bound on a single echo message (bytes). Bounds server-side reads so a peer cannot
/// force unbounded allocation on the pds.
const MAX_MESSAGE_LEN: usize = 64 * 1024;

/// Maximum time for one echo stream exchange (read request → write reply). Bounds exposure to
/// a peer that stalls either side: never closing its send half (parking `read_to_end`) or
/// never draining its receive window (parking `write_all` on QUIC flow control). Without it
/// such a peer would hold the connection task open indefinitely.
const STREAM_TIMEOUT: std::time::Duration = std::time::Duration::from_secs(30);

/// Process-level Iroh endpoint state, shared via `AppState` behind an `Arc`.
pub struct IrohState {
    /// The bound endpoint. Cheaply cloneable (internally reference-counted); the accept loop
    /// holds one clone, handlers reach it through `AppState`.
    pub endpoint: Endpoint,
    /// The endpoint's node id rendered as a string — the value advertised to devices.
    pub node_id: String,
}

/// Build and bind an Iroh endpoint using the pds's persistent secret key.
///
/// Uses the `N0` preset (n0 discovery + relays) so a device can dial the pds by node id
/// alone — discovery resolves the pds's reachable addresses and QUIC holepunches through
/// NAT. The endpoint accepts only the `ezpds/iroh/0` ALPN.
///
/// The builder pre-configures both an IPv4 (`0.0.0.0`) and an IPv6 (`[::]`) socket. When
/// `ipv6` is false (a v4-only host — e.g. a Railway container with no public v6 egress), we
/// clear the pre-configured transports and re-bind IPv4 only, so iroh never opens the v6
/// socket whose relay probes would otherwise fail with `NetworkUnreachable` forever.
pub async fn start(secret: [u8; 32], ipv6: bool) -> anyhow::Result<IrohState> {
    let secret_key = SecretKey::from_bytes(&secret);
    let mut builder = Endpoint::builder(presets::N0)
        .secret_key(secret_key)
        .alpns(vec![ALPN.to_vec()]);
    if !ipv6 {
        builder = builder
            .clear_ip_transports()
            .bind_addr("0.0.0.0:0")
            .map_err(|e| anyhow::anyhow!("invalid IPv4 bind address for v4-only iroh: {e}"))?;
    }
    let endpoint = builder
        .bind()
        .await
        .map_err(|e| anyhow::anyhow!("failed to bind Iroh endpoint: {e}"))?;
    let node_id = endpoint.id().to_string();
    Ok(IrohState { endpoint, node_id })
}

/// Spawn the accept loop as a detached background task.
///
/// Fire-and-forget like the blob GC: the returned handle can be dropped. The loop runs until
/// the endpoint is closed (`endpoint.close()` makes `accept()` yield `None`), at which point
/// the task ends. Per-connection errors are logged, never propagated — one misbehaving peer
/// never stops the loop.
pub fn spawn_accept_loop(endpoint: Endpoint) -> tokio::task::JoinHandle<()> {
    tokio::spawn(async move {
        while let Some(incoming) = endpoint.accept().await {
            tokio::spawn(async move {
                if let Err(e) = handle_connection(incoming).await {
                    tracing::debug!(error = %e, "iroh connection ended with error");
                }
            });
        }
        tracing::info!("iroh accept loop stopped (endpoint closed)");
    })
}

/// Handle one accepted connection: echo every bidirectional stream until the peer hangs up.
async fn handle_connection(incoming: Incoming) -> anyhow::Result<()> {
    let connection = incoming.accept()?.await?;
    let remote = connection.remote_id();
    tracing::debug!(%remote, "iroh connection accepted");

    // v0.1 protocol: for each bi stream the peer opens, read the request and write the same
    // bytes back. `accept_bi` erroring means the peer closed the connection — a clean exit.
    loop {
        let (mut send, mut recv) = match connection.accept_bi().await {
            Ok(streams) => streams,
            Err(_) => break,
        };
        // Bound the whole exchange under one deadline so a peer cannot stall the read (never
        // closing its send half) or the write (never draining our reply) to pin this task.
        let exchange = async {
            let msg = recv.read_to_end(MAX_MESSAGE_LEN).await?;
            send.write_all(&msg).await?;
            send.finish()?;
            Ok::<(), anyhow::Error>(())
        };
        tokio::time::timeout(STREAM_TIMEOUT, exchange)
            .await
            .map_err(|_| anyhow::anyhow!("iroh stream exchange timed out"))??;
    }
    Ok(())
}

/// Bind an offline endpoint for tests: the `Minimal` preset sets only the rustls crypto
/// provider (no relay, no DNS discovery), and binding to loopback keeps everything local and
/// deterministic — no network required. With `with_alpn`, the endpoint accepts the ezpds ALPN
/// (pds side); without it, the endpoint can only dial (device side).
#[cfg(test)]
pub(crate) async fn loopback_endpoint(with_alpn: bool) -> Endpoint {
    let mut builder = Endpoint::builder(presets::Minimal)
        .bind_addr("127.0.0.1:0")
        .expect("valid bind addr");
    if with_alpn {
        builder = builder.alpns(vec![ALPN.to_vec()]);
    }
    builder.bind().await.expect("bind loopback endpoint")
}

/// Build an offline [`IrohState`] bound to loopback, for tests in other modules (e.g. the
/// `get_device_pds` handler) that need a running endpoint with a real node id.
#[cfg(test)]
pub(crate) async fn loopback_state() -> IrohState {
    let endpoint = loopback_endpoint(true).await;
    let node_id = endpoint.id().to_string();
    IrohState { endpoint, node_id }
}

