        let mut f = crate::firehose::Firehose::new(db.clone())
            .await
            .expect("test firehose");
        f.attach_metrics(metrics.clone());
        f
    });

    AppState {
        config: Arc::new(Config {
            bind_address: "127.0.0.1".to_string(),
            port: 8080,
